setup.hook_script:
#!/bin/sh
while read old new ref; do
  subj=$(git log -1 --format=%s "$new")
  echo "remote: [ok] scanning $ref" >&2
  case "$subj" in
    [A-Z]*-[0-9]*" "*) ;;
    *) echo 'remote: error: commit subject must start with a ticket id like OPS-123' >&2; exit 1;;
  esac
done
exit 0

